#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int n; vector<vector<pair<int,ll>>> adj;
vector<ll> jarakDari(int s) { // pohon: DFS iteratif cukup untuk jarak
    vector<ll> d(n + 1, -1); d[s] = 0; vector<int> st = {s};
    while (!st.empty()) { int u = st.back(); st.pop_back(); for (auto [v, w] : adj[u]) if (d[v] < 0) { d[v] = d[u] + w; st.push_back(v); } }
    return d;
}
int main() {
    scanf("%d", &n); adj.resize(n + 1);
    for (int i = 0; i < n - 1; i++) { int u, v; ll w; scanf("%d %d %lld", &u, &v, &w); adj[u].push_back({v, w}); adj[v].push_back({u, w}); }
    // Rumah terjauh dari mana pun selalu salah satu ujung diameter (a atau b).
    auto d1 = jarakDari(1); int a = max_element(d1.begin() + 1, d1.end()) - d1.begin();
    auto da = jarakDari(a); int b = max_element(da.begin() + 1, da.end()) - da.begin();
    auto db = jarakDari(b);
    ll total = 0; for (int i = 1; i <= n; i++) total += max(da[i], db[i]);
    printf("%lld\n", total);
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll; const ll MOD = 1000000007; int n;
typedef vector<vector<ll>> M;
M kali(const M &a, const M &b) { M c(n, vector<ll>(n, 0)); for (int i = 0; i < n; i++) for (int k = 0; k < n; k++) if (a[i][k]) for (int j = 0; j < n; j++) c[i][j] = (c[i][j] + a[i][k] * b[k][j]) % MOD; return c; }
int main() {
    ll k; scanf("%d %lld", &n, &k); M g(n, vector<ll>(n));
    for (auto &r : g) for (auto &x : r) scanf("%lld", &x);
    M h(n, vector<ll>(n, 0)); for (int i = 0; i < n; i++) h[i][i] = 1; // identitas
    while (k) { if (k & 1) h = kali(h, g); g = kali(g, g); k >>= 1; }
    printf("%lld\n", h[0][n - 1]);
}

