#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1000000007;
long long pw(long long a, long long b) { long long r = 1; a %= MOD; while (b) { if (b & 1) r = r * a % MOD; a = a * a % MOD; b >>= 1; } return r; }
int main() {
    const int N = 1000000;
    vector<long long> f(N + 1), inv(N + 1);
    f[0] = 1; for (int i = 1; i <= N; i++) f[i] = f[i - 1] * i % MOD;
    inv[N] = pw(f[N], MOD - 2); // Fermat: a^(p-2) = a^-1 mod p
    for (int i = N; i > 0; i--) inv[i - 1] = inv[i] * i % MOD;
    int q; scanf("%d", &q); long long total = 0;
    while (q--) { int n, r; scanf("%d %d", &n, &r); total = (total + f[n] * inv[r] % MOD * inv[n - r]) % MOD; }
    printf("%lld\n", total);
}

