#include <bits/stdc++.h>
using namespace std;
int sz; vector<long long> t;
void ubah(int i, long long x) { for (t[i += sz] = x; i > 1; i >>= 1) t[i >> 1] = min(t[i], t[i ^ 1]); }
long long minimum(int l, int r) { long long m = LLONG_MAX; for (l += sz, r += sz + 1; l < r; l >>= 1, r >>= 1) { if (l & 1) m = min(m, t[l++]); if (r & 1) m = min(m, t[--r]); } return m; }
int main() {
    int n, q; scanf("%d %d", &n, &q);
    sz = 1; while (sz < n) sz <<= 1; t.assign(2 * sz, LLONG_MAX);
    for (int i = 0; i < n; i++) scanf("%lld", &t[sz + i]);
    for (int i = sz - 1; i > 0; i--) t[i] = min(t[2 * i], t[2 * i + 1]);
    long long total = 0;
    while (q--) { int k; long long a, b; scanf("%d %lld %lld", &k, &a, &b); if (k == 1) ubah(a - 1, b); else total += minimum(a - 1, b - 1); }
    printf("%lld\n", total);
}

