#include <bits/stdc++.h>
using namespace std;
typedef unsigned long long u64;
int main() {
    static char s[200005]; int L; scanf("%s %d", s, &L); int n = strlen(s);
    // hash ganda: modulo 2^61−1 dengan dua basis berbeda (peluang tabrakan sangat kecil)
    const u64 MOD = (1ULL << 61) - 1;
    auto mul = [&](u64 a, u64 b) { __uint128_t c = (__uint128_t)a * b; u64 r = (u64)(c & MOD) + (u64)(c >> 61); return r >= MOD ? r - MOD : r; };
    auto hashes = [&](u64 B) {
        u64 pw = 1; for (int i = 0; i < L; i++) pw = mul(pw, B);
        vector<u64> h; u64 cur = 0;
        for (int i = 0; i < n; i++) {
            cur = mul(cur, B) + (u64)s[i]; if (cur >= MOD) cur -= MOD;
            if (i >= L) { u64 sub = mul(pw, (u64)s[i - L]); cur = cur >= sub ? cur - sub : cur + MOD - sub; }
            if (i >= L - 1) h.push_back(cur);
        }
        return h;
    };
    auto h1 = hashes(911382323), h2 = hashes(972663749);
    vector<pair<u64,u64>> all(h1.size()); for (size_t i = 0; i < h1.size(); i++) all[i] = {h1[i], h2[i]};
    sort(all.begin(), all.end());
    printf("%zu\n", (size_t)(unique(all.begin(), all.end()) - all.begin()));
}

