using namespace std;
typedef long long ll; typedef pair<ll,ll> P;
__int128 cross(P o, P a, P b) { return (__int128)(a.first - o.first) * (b.second - o.second) - (__int128)(a.second - o.second) * (b.first - o.first); }
int main() {
    int n; scanf("%d", &n); vector<P> p(n); for (auto &x : p) scanf("%lld %lld", &x.first, &x.second);
    sort(p.begin(), p.end()); p.erase(unique(p.begin(), p.end()), p.end()); n = p.size();
    if (n < 3) { puts("0"); return 0; }
    vector<P> h(2 * n); int k = 0; // monotone chain (Andrew)
    for (int i = 0; i < n; i++) { while (k >= 2 && cross(h[k - 2], h[k - 1], p[i]) <= 0) k--; h[k++] = p[i]; }
    for (int i = n - 2, t = k + 1; i >= 0; i--) { while (k >= t && cross(h[k - 2], h[k - 1], p[i]) <= 0) k--; h[k++] = p[i]; }
    h.resize(k - 1);
    __int128 a = 0; for (size_t i = 0; i < h.size(); i++) { auto [x1, y1] = h[i]; auto [x2, y2] = h[(i + 1) % h.size()]; a += (__int128)x1 * y2 - (__int128)x2 * y1; }
    if (a < 0) a = -a;
    string s; do { s += char('0' + (int)(a % 10)); a /= 10; } while (a > 0); reverse(s.begin(), s.end()); printf("%s\n", s.c_str());
}

