using namespace std;
int main() {
    int n, q; scanf("%d %d", &n, &q);
    const int LOG = 18; vector<array<int, LOG>> up(n + 1); vector<int> dep(n + 1, 0);
    up[1].fill(1);
    for (int i = 2; i <= n; i++) { int p; scanf("%d", &p); up[i][0] = p; dep[i] = dep[p] + 1; for (int k = 1; k < LOG; k++) up[i][k] = up[up[i][k - 1]][k - 1]; }
    long long total = 0;
    while (q--) {
        int a, b; scanf("%d %d", &a, &b); int x = a, y = b;
        if (dep[x] < dep[y]) swap(x, y);
        for (int k = LOG - 1; k >= 0; k--) if (dep[x] - (1 << k) >= dep[y]) x = up[x][k];
        if (x != y) { for (int k = LOG - 1; k >= 0; k--) if (up[x][k] != up[y][k]) { x = up[x][k]; y = up[y][k]; } x = up[x][0]; }
        total += dep[a] + dep[b] - 2 * dep[x];
    }
    printf("%lld\n", total);
}

