#include <bits/stdc++.h>
using namespace std;
int n, k; vector<long long> w;
bool bisa(long long batas) { // greedy: isi gagak sampai penuh
    int gagak = 1; long long beban = 0;
    for (long long x : w) {
        if (x > batas) return false;
        if (beban + x > batas) { gagak++; beban = 0; }
        beban += x;
    }
    return gagak <= k;
}
int main() {
    scanf("%d %d", &n, &k); w.resize(n);
    for (auto &x : w) scanf("%lld", &x);
    long long lo = 1, hi = 0; for (auto x : w) hi += x;
    while (lo < hi) { long long mid = (lo + hi) / 2; if (bisa(mid)) hi = mid; else lo = mid + 1; }
    printf("%lld\n", lo);
}

